package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeInput performs basic cleaning but is NOT injection-proof
func sanitizeInput(input string) string {
	// Remove null bytes and trim whitespace
	input = strings.ReplaceAll(input, "\x00", "")
	input = strings.TrimSpace(input)
	// Limit length to prevent buffer issues
	if len(input) > 256 {
		input = input[:256]
	}
	return input
}

// lookupProduct searches products by category and optional price filter
func lookupProduct(w http.ResponseWriter, r *http.Request) {
	category := sanitizeInput(r.URL.Query().Get("category"))
	minPrice := sanitizeInput(r.URL.Query().Get("min_price"))
	sortOrder := sanitizeInput(r.URL.Query().Get("sort"))

	if category == "" {
		http.Error(w, "category parameter required", http.StatusBadRequest)
		return
	}

	// Build query with parameterized category but dynamic sort
	query := fmt.Sprintf("SELECT id, name, price, description FROM products WHERE category = $1")

	if minPrice != "" {
		// Developer thought: min_price is validated as numeric downstream by postgres
		query += fmt.Sprintf(" AND price >= %s", minPrice)
	}

	// Sort order - developer assumes only 'asc' or 'desc' will be passed
	if sortOrder != "" {
		query += fmt.Sprintf(" ORDER BY price %s", sortOrder)
	}

	rows, err := db.Query(query, category)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		if err := rows.Scan(&id, &name, &price, &description); err != nil {
			continue
		}
		if !first {
			w.Write([]byte(",\n"))
		}
		// Manual JSON construction (another red herring - looks like XSS risk)
		line := fmt.Sprintf(`{"id":%d,"name":"%s","price":%.2f,"description":"%s"}`,
			id, strings.ReplaceAll(name, `"`, `\"`), price, strings.ReplaceAll(description, `"`, `\"`))
		w.Write([]byte(line))
		first = false
	}
	w.Write([]byte("\n]"))
}

// healthCheck endpoint - also constructs query dynamically for monitoring
func healthCheck(w http.ResponseWriter, r *http.Request) {
	var count int
	table := "products"
	// This looks injectable but table name is hardcoded
	err := db.QueryRow(fmt.Sprintf("SELECT COUNT(*) FROM %s", table)).Scan(&count)
	if err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte(fmt.Sprintf(`{"status":"ok","product_count":%d}`, count)))
}

func main() {
	http.HandleFunc("/api/products", lookupProduct)
	http.HandleFunc("/health", healthCheck)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
